-- ============================================================
-- V22: Append the Animation contract + a motion-annotated worked example
-- to the Video Script Generator skill so the LLM emits per-scene animation
-- plans (entrance/stagger, bullet reveal, highlights, progress, chart draw-in)
-- and scene-level transitions for presentation-style educational videos.
-- ============================================================

UPDATE public.skills
SET content = content || E'\n\n## Animation contract (motion for every scene)\nEvery scene object may carry an optional "animation" object that the video engine plays back frame-accurately, synced to the narration voiceover. Use it generously so videos feel like a live presentation, not static slides.\n\nAllowed fields:\n- "entrance": one of "fade-up" (default), "fade-in", "slide-left", "slide-right", "zoom-in", "none".\n- "stagger": seconds between consecutive components/cards appearing (0.3-0.6 works well; use 0.4).\n- "bullets": true to reveal list items / timeline nodes one-by-one in sync with narration.\n- "progress": true to show a thin progress bar under the scene.\n- "drawCharts": true to animate bar/line/pie charts drawing in.\n- "highlights": array of { "id": "<component id>", "at": <seconds>, "color": "#hex", "style": "glow" } - highlights a component with a glowing ring at the given narration second.\n\nRules:\n- Give every component a unique "id" so highlights can target it.\n- Always set "animation" per scene; never leave it out.\n- The highlight "at" value must fall inside the scene narration window (roughly 0 to scene duration in seconds).\n- Keep one "progress": true per video (usually the last scene) rather than on every scene.\n\n### Worked example - motion-annotated scene (layout "flow" + animation)\n{\n  "title": "STACK ALLOCATION",\n  "subtitle": "How method calls use memory",\n  "theme": "technical",\n  "layout": "flow",\n  "components": [\n    { "id": "a", "type": "oval", "label": "MAIN", "fill": "#eff6ff", "line": "#2563eb" },\n    { "id": "b", "type": "box", "label": "CALL foo()", "fill": "#fef3c7", "line": "#d97706" },\n    { "id": "c", "type": "box", "label": "PUSH FRAME", "fill": "#fce7f3", "line": "#db2777" },\n    { "id": "d", "type": "box", "label": "RETURN", "fill": "#f0fdf4", "line": "#16a34a" }\n  ],\n  "connections": [\n    { "from": "a", "to": "b", "kind": "default" },\n    { "from": "b", "to": "c", "kind": "default" },\n    { "from": "c", "to": "d", "kind": "default" }\n  ],\n  "animation": {\n    "entrance": "fade-up",\n    "stagger": 0.4,\n    "bullets": true,\n    "drawCharts": false,\n    "highlights": [ { "id": "c", "at": 2.0, "color": "#db2777", "style": "glow" } ]\n  },\n  "instructions": [ "Each call allocates a new frame on the stack" ]\n}'
WHERE id = 'a0000000-0000-0000-0000-000000000001'
  AND content NOT LIKE '%Animation contract (motion for every scene)%';
